edits.from:
image({ href, text }) {
  return anchor(href, escape(text));
},

edits.to:
image({ href, text }) {
  return `<img src="${escape(href)}" alt="${escape(text)}">`;
},

edits.from:
if (typeof entry.line === "string") {
  return { who: entry.from, kind: "line", text: entry.line, err: entry.err === true };
}
